def merge_brackets(s, t):
    result = []
    i, j = 0, 0
    balance = 0

    while i < len(s) and j < len(t):
        if balance == 0:
            if s[i] == t[j]:
                result.append(s[i])
                i += 1
                j += 1
            else:
                result.append(s[i])
                result.append(t[j])
                i += 1
                j += 1
        else:
            if s[i] == '(' and t[j] == '(':
                result.append(s[i])
                i += 1
            elif s[i] == ')' and t[j] == ')':
                result.append(s[i])
                i += 1
                j += 1
            elif s[i] == '(' and t[j] == ')':
                result.append(s[i])
                i += 1
            elif s[i] == ')' and t[j] == '(':
                result.append(t[j])
                j += 1
        balance += 1 if s[i-1] == '(' else -1

    while i < len(s):
        result.append(s[i])
        i += 1

    while j < len(t):
        result.append(t[j])
        j += 1

    return ''.join(result)

# Read input
s = input().strip()
t = input().strip()

# Output the result
print(merge_brackets(s, t))
